61	export function StudentStandby() {
62	  const { user } = useAuth();
63	  const { activeLocation } = useLocation2();
64	
65	  const [entries, setEntries] = useState<StandbyEntry[]>([]);
66	  const [loading, setLoading] = useState(true);
67	  const [showAdd, setShowAdd] = useState(false);
68	  const [addForm, setAddForm] = useState({
