77	
78	  const locationId = activeLocation?.id ?? '';
79	  const studentId = user?.appUserId ?? '';
80	
81	  const fetchEntries = useCallback(async () => {
82	    if (!locationId || !studentId) return;
83	    setLoading(true);
84	    try {
85	      const res = await fetch(
86	        `/api/server/locations/${locationId}/students/${studentId}/standby`,
