88	      if (res.ok) {
89	        const data = (await res.json()) as { requests: StandbyEntry[] };
90	        setEntries(data.requests ?? []);
91	      }
92	    } finally {
93	      setLoading(false);
94	    }
95	  }, [locationId, studentId]);
96	
97	  useEffect(() => {
98	    void fetchEntries();
99	  }, [fetchEntries]);
100	
101	  async function handleAdd() {
102	    if (!locationId || !addForm.requestedDate || !studentId) return;
103	    setSubmitting(true);
104	    setError(null);
105	    try {
106	      const res = await fetch(
107	        `/api/server/locations/${locationId}/schedule/standby`,
108	        {
109	          method: 'POST',
110	          headers: { 'Content-Type': 'application/json' },
111	          body: JSON.stringify({
