117	            requestedEndHour: addForm.requestedEndHour
118	              ? Number(addForm.requestedEndHour)
119	              : undefined,
120	            eventType: addForm.eventType,
121	            notes: addForm.notes || undefined,
122	          }),
123	        },
124	      );
125	      if (!res.ok) {
126	        const d = (await res.json()) as { error?: string };
127	        setError(d.error ?? 'Failed to join standby');
128	        return;
129	      }
130	      setShowAdd(false);
131	      setAddForm({
132	        requestedDate: '',
133	        requestedStartHour: '',
134	        requestedEndHour: '',
135	        eventType: 'flight',
136	        notes: '',
137	      });
138	      void fetchEntries();
139	    } finally {
140	      setSubmitting(false);
141	    }
142	  }
143	
144	  async function handleCancel(id: string) {
145	    if (!locationId) return;
146	    await fetch(`/api/server/locations/${locationId}/schedule/standby/${id}`, {
147	      method: 'DELETE',
148	    });
